steps.run:
if ($env:RUNNER_NAME -ne $env:EXPECTED_RUNNER_NAME) {
  throw "Expected $env:EXPECTED_RUNNER_NAME but routed to $env:RUNNER_NAME"
}
$drive = (Get-Item $env:GITHUB_WORKSPACE).PSDrive.Name
$disk = [math]::Round((Get-PSDrive $drive).Free / 1GB, 1)
$memory = [math]::Round((Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory / 1MB, 1)
$line = @{ runner = $env:RUNNER_NAME; os = 'Windows'; disk_free_gb = $disk; mem_available_gb = $memory } | ConvertTo-Json -Compress
Write-Output "COMPUTE_PANEL_PROBE $line"
# Node governance level from the node's one status file; never fails the probe.
$level = 'unknown'; $written = $null
try {
  $row = Get-Content -Raw -LiteralPath 'C:\ProgramData\Clued\node-governance\status.json' -ErrorAction Stop | ConvertFrom-Json
  if (@('green', 'yellow', 'red') -ccontains $row.level) { $level = $row.level }
  if ($row.writtenAt -is [string]) { $written = $row.writtenAt.Substring(0, [math]::Min(64, $row.writtenAt.Length)) }
  elseif ($row.writtenAt -is [datetime]) { $written = $row.writtenAt.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
} catch { }
$governance = [ordered]@{ level = $level; writtenAt = $written } | ConvertTo-Json -Compress
Write-Output "COMPUTE_PANEL_GOVERNANCE $governance"

